// Home page board + pickup panel: runs on records.onDataQuerySuccess and the Home page's onPageLoad
const e = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const rows = queries.records.data || [];
const n = r => r.subject || r.title || r.name || r.reference || r.request || 'Untitled';
const s = r => r.state || r.stage || r.status || 'Open';
const o = r => r.owner || r.assignee || r.crew || 'Unassigned';
const open = rows.filter(r => !['Completed', 'Closed', 'Collected'].includes(s(r)));
// board lane label and the work order state it lists
const stages = [['Checked in', 'Booked'], ['Diagnosing', 'Diagnosing'], ['In repair', 'Repairing'], ['Ready', 'Ready']];
const colors = ['#EDF3F5', '#F3F0EA', '#EDF0F6', '#EBF4EF'];
const ready = rows.filter(r => /ready|complete/i.test(s(r)));
return {
  lanes: stages.map(([stage, state], i) => {
    const inLane = open.filter(r => s(r) === state);
    const [a, b] = inLane;
    return { stage, color: colors[i], count: inLane.length, c1name: a ? e(n(a)) : '', c1owner: a ? e(o(a)) : '', c2name: b ? e(n(b)) : '', c2owner: b ? e(o(b)) : '' };
  }),
  readyCount: ready.length,
  ready: ready.slice(0, 3).map(r => ({ name: n(r), owner: o(r) }))
};
